.ds-crt {
  position: relative;
  container-type: inline-size;
  /* Sized so the whole rack (header, shelf, tube, deck, footer) shares the
     first desktop viewport; playback legibility comes from the dolly. */
  width: clamp(300px, min(400px, calc((100vh - 640px) * 1.3333 + 38px)), 100%);
  margin-inline: auto;
}

.ds-bezel {
  background: var(--ink-2);
  border: 1px solid var(--seam);
  border-radius: var(--r-bezel);
  padding: 18px;
  box-shadow: var(--edge-lit), var(--shadow-unit);
}

/*
 * The screen is the page's only light source (One Light Rule): its bloom is
 * the single permitted outward glow, and every retro effect below is clipped
 * to this element.
 */
.ds-screen {
  position: relative;
  aspect-ratio: 4 / 3;
  border-radius: 12px;
  overflow: hidden;
  background: var(--screen-black);
  transition:
    box-shadow var(--t-med),
    background var(--t-med);
  box-shadow: var(--bloom-rest);
}

.ds-idle,
.ds-ejecting {
  background: var(--crt-blue);
  box-shadow: var(--bloom-idle);
}

.ds-playing {
  box-shadow: var(--bloom-play);
}

/* Diegetic layers — inside the tube only. */

/* Live phosphor grain: a tiny desaturated turbulence tile stepped through
   four offsets (~5 fps, like a broadcast). Faint enough that prose contrast
   is untouched; the reduced-motion gate leaves it as a static texture. */
.ds-grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background-image: url("data:image/svg+xml,%3Csvg xmlns='http://www.ds-w3.org/2000/svg' width='160' height='160'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='2' stitchTiles='stitch'/%3E%3CfeColorMatrix type='saturate' values='0'/%3E%3C/filter%3E%3Crect width='160' height='160' filter='url(%23n)'/%3E%3C/svg%3E");
  background-size: 160px 160px;
  opacity: 0.05;
  animation: ds-grainShift 0.8s steps(1, end) infinite;
}

@keyframes ds-grainShift {
  0% {
    background-position: 0 0;
  }
  25% {
    background-position: 80px 48px;
  }
  50% {
    background-position: 32px 112px;
  }
  75% {
    background-position: 128px 64px;
  }
  100% {
    background-position: 0 0;
  }
}

.ds-scan {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: repeating-linear-gradient(
    0deg,
    rgba(0, 0, 0, 0.17) 0 1px,
    transparent 1px 3px
  );
  opacity: 0.35;
}

.ds-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: inherit;
  background: radial-gradient(
    115% 115% at 50% 50%,
    transparent 62%,
    rgba(0, 0, 0, 0.5) 100%
  );
}

/* Brief tracking wobble when a tape starts (remounted per slug). */
.ds-track {
  position: absolute;
  inset: 0;
  animation: ds-track 400ms steps(6, end) 1;
}

@keyframes ds-track {
  0% {
    transform: translateY(-6%);
    filter: brightness(2.1);
  }
  30% {
    transform: translateY(3%);
    filter: brightness(1.3);
  }
  55% {
    transform: translateY(-1.5%);
  }
  100% {
    transform: none;
    filter: none;
  }
}

/* OSD chrome floats over the picture; its glow is inside the screen. */
.ds-osd {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  display: flex;
  justify-content: space-between;
  padding: 0.875rem 5cqi;
  font-family: var(--font-osd);
  font-size: clamp(1.125rem, 4.5cqi, 1.375rem);
  line-height: 1.2;
  font-variant-numeric: tabular-nums;
  color: var(--osd);
  text-shadow: 0 0 6px rgba(255, 255, 255, 0.5);
  z-index: 2;
  pointer-events: none;
}

.ds-reader {
  position: absolute;
  inset: 0;
  overflow-y: auto;
  padding: 4rem 9% 2.75rem;
  font-size: clamp(1rem, 3.1cqi, 1.0625rem);
  font-weight: 440;
  letter-spacing: 0.005em;
  overflow-wrap: anywhere;
  scrollbar-width: thin;
  scrollbar-color: var(--seam-lit) transparent;
}

.ds-reader-content {
  max-width: 62ch;
  margin-inline: auto;
}

.ds-reader:focus-visible {
  outline: 2px solid var(--osd);
  outline-offset: -4px;
  border-radius: inherit;
}

.ds-title {
  font-weight: 800;
  font-stretch: 110%;
  font-size: clamp(1.5rem, 5.6cqi, 2rem);
  line-height: 1.12;
  letter-spacing: -0.015em;
  text-transform: uppercase;
  text-wrap: balance;
  color: var(--screen-text);
  margin-bottom: 0.5em;
}

/* Focus cue as OSD emphasis: a clear underline, not a box around a
   screen-filling heading. */
.ds-title:focus-visible,
.ds-bigOsd:focus-visible {
  outline: none;
  text-decoration: underline;
  text-decoration-thickness: 3px;
  text-decoration-color: var(--osd);
  text-underline-offset: 0.28em;
}

.ds-meta {
  font-family: var(--font-osd);
  font-size: clamp(1.0625rem, 4cqi, 1.25rem);
  font-weight: 400;
  line-height: 1.35;
  font-variant-numeric: tabular-nums;
  color: var(--screen-dim);
  margin-bottom: 1.2em;
}

.ds-tagline {
  font-weight: 600;
  font-size: inherit;
  line-height: 1.5;
  color: var(--screen-text);
  text-wrap: pretty;
  margin-bottom: 1em;
}

.ds-para {
  font-size: inherit;
  line-height: 1.65;
  color: var(--screen-text);
  text-wrap: pretty;
  margin-bottom: 1em;
}

.ds-gallery {
  display: grid;
  gap: var(--sp-md);
  margin: var(--sp-lg) 0;
}

.ds-gallery img,
.ds-gallery video {
  border: 1px solid var(--seam);
  border-radius: var(--r-control);
  width: 100%;
}

.ds-gallery figcaption {
  font-family: var(--font-osd);
  font-size: clamp(1.0625rem, 4cqi, 1.25rem);
  font-weight: 400;
  line-height: 1.35;
  color: var(--screen-dim);
  margin-top: var(--sp-xs);
}

.ds-tags {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sp-sm) var(--sp-md);
  font-family: var(--font-osd);
  font-size: clamp(1.0625rem, 4cqi, 1.25rem);
  font-weight: 400;
  line-height: 1.35;
  color: var(--screen-soft);
  margin: var(--sp-lg) 0 var(--sp-md);
}

.ds-links {
  display: flex;
  flex-wrap: wrap;
  gap: var(--sp-sm) var(--sp-md);
  margin-bottom: var(--sp-lg);
}

.ds-links a {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-width: 44px;
  min-height: 44px;
  font-family: var(--font-osd);
  font-size: clamp(1.0625rem, 4cqi, 1.25rem);
  font-weight: 400;
  line-height: 1.35;
  color: var(--osd);
  text-decoration: none;
  border: 1px solid var(--osd);
  border-radius: var(--r-hairline);
  padding: 6px 14px;
  transition:
    background var(--t-fast),
    color var(--t-fast);
}

.ds-links a:hover {
  background: var(--osd);
  color: var(--screen-black);
}

.ds-links a:focus-visible {
  outline-color: var(--osd);
}

.ds-end {
  font-family: var(--font-osd);
  font-size: clamp(1.0625rem, 4cqi, 1.25rem);
  font-weight: 400;
  line-height: 1.35;
  font-variant-numeric: tabular-nums;
  color: var(--screen-dim);
}

/* REC blinks while a tape plays — the tube's own heartbeat. Solid under
   the reduced-motion gate. */
.ds-rec {
  color: var(--rec-red);
  animation: ds-blink 1.2s steps(2, start) infinite;
}

/* Idle / NO SIGNAL center stage. */
.ds-centerScreen {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: var(--sp-md);
  font-family: var(--font-osd);
  color: var(--osd);
  text-align: center;
  padding: var(--sp-lg);
  overflow-wrap: anywhere;
}

.ds-bigOsd {
  font-size: clamp(1.5rem, 9cqi, 2.5rem);
  font-weight: 400;
  line-height: 1.2;
  letter-spacing: 0.06em;
  text-shadow: 0 0 10px rgba(255, 255, 255, 0.45);
}

.ds-subOsd {
  font-size: clamp(1.0625rem, 4cqi, 1.25rem);
  line-height: 1.35;
  color: var(--screen-soft);
}

.ds-cursor {
  margin-left: 8px;
  animation: ds-blink 1.1s steps(2, start) infinite;
}

@keyframes ds-blink {
  50% {
    opacity: 0;
  }
}

.ds-cornerTL,
.ds-cornerBR {
  position: absolute;
  font-size: clamp(1.0625rem, 4cqi, 1.25rem);
  text-shadow: 0 0 6px rgba(255, 255, 255, 0.5);
}

.ds-cornerTL {
  top: 14px;
  left: 20px;
}

.ds-cornerBR {
  bottom: 14px;
  right: 20px;
}

.ds-chin {
  text-align: center;
  margin-top: var(--sp-sm);
  letter-spacing: 0.2em;
}

/* The screen's light falling on the deck below — the one permitted cast.
   Anchored at the bezel's lower edge (over the chin label) so the falloff
   is continuous from where the light physically exits; it must fade out
   fully before the strip ends. */
.ds-cast {
  position: absolute;
  top: calc(100% - 22px);
  left: 8%;
  right: 8%;
  height: 120px;
  pointer-events: none;
  z-index: 2;
  background: var(--cast-idle);
  transition: opacity var(--t-med);
}

.ds-castPlay {
  background: var(--cast-play);
}

/* Playing on a small screen: the CRT pins near-fullscreen, still a CRT. */
@media (max-width: 719px) {
  .ds-crt {
    width: 100%;
  }

  :global(.ds-playing-stage) .ds-crt {
    position: fixed;
    top: 8px;
    left: 8px;
    right: 8px;
    bottom: 88px;
    z-index: 30;
    width: auto;
    display: flex;
    flex-direction: column;
  }

  :global(.ds-playing-stage) .ds-bezel {
    flex: 1;
    display: flex;
    padding: 12px;
  }

  :global(.ds-playing-stage) .ds-screen {
    aspect-ratio: auto;
    flex: 1;
  }

  :global(.ds-playing-stage) .ds-chin,
  :global(.ds-playing-stage) .ds-cast {
    display: none;
  }

  .ds-reader {
    padding: 4rem 6% 2.5rem;
  }
}

/* Native HTML stays crisp and selectable on the actual 3D screen plane. */
.ds-embedded {
  width: 100%;
}
.ds-embedded .ds-bezel {
  padding: 0;
  border: 0;
  border-radius: 14px;
  background: transparent;
  box-shadow: none;
}
.ds-embedded .ds-screen {
  aspect-ratio: 4 / 3;
  border-radius: 14px;
}
.ds-embedded .ds-chin,
.ds-embedded .ds-cast {
  display: none;
}
.ds-embedded .ds-osd {
  background: linear-gradient(var(--screen-black) 70%, transparent);
  padding-bottom: 1.375rem;
}
.ds-embedded .ds-reader {
  overscroll-behavior: contain;
}
.ds-embedded .ds-bigOsd {
  font-weight: 400;
}

.ds-fullHeight,
.ds-fullHeight .ds-bezel,
.ds-fullHeight .ds-screen {
  height: 100%;
}
.ds-fullHeight .ds-screen {
  aspect-ratio: auto;
}
.ds-fullHeight .ds-reader {
  padding: 4rem 7% 2.5rem;
  font-size: clamp(1rem, 2.4cqi, 1.125rem);
}
.ds-fullHeight .ds-title {
  font-size: clamp(1.5rem, 7.5cqi, 2rem);
}

